function c(t){if(typeof t=="number"){if(!Number.isFinite(t))throw new Error("Invalid amount");return Math.round(t*100)}const r=t.trim().replace(/,/g,"");if(!r)return 0;if(!/^-?\d*(\.\d{0,2})?$/.test(r))throw new Error("Invalid amount format");const[n,a=""]=r.split("."),e=n.startsWith("-")?-1:1,o=Math.abs(Number(n||"0")),i=(a+"00").slice(0,2);return e*(o*100+Number(i))}function u(t){const r=t<0?"-":"",n=Math.abs(t),a=Math.floor(n/100),e=String(n%100).padStart(2,"0");return`${r}${a}.${e}`}const s=new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",minimumFractionDigits:2,maximumFractionDigits:2});function m(t){return s.format(t/100)}function f(t,r="en-IN"){try{const n=new Date(t);return new Intl.DateTimeFormat(r,{day:"2-digit",month:"short",year:"numeric"}).format(n)}catch{return t}}function d(){return new Date().toISOString().slice(0,10)}export{f as a,m as f,u as p,c as r,d as t};
